// The initial values of both before_length and after_length are 0.
type ZwpTextInputV3DeleteSurroundingTextEvent struct {
	// BeforeLength: length of text before current cursor position.
	BeforeLength uint32
	// AfterLength: length of text after current cursor position.
	AfterLength uint32
}

// SetDeleteSurroundingTextHandler sets the callback for the delete_surrounding_text event. Pass nil to remove it.
func (self *ZwpTextInputV3) SetDeleteSurroundingTextHandler(h func(ZwpTextInputV3DeleteSurroundingTextEvent)) {
	self.onDeleteSurroundingText = h
}

// ZwpTextInputV3DoneEvent holds the arguments of the zwp_text_input_v3.done event: apply changes.
//
// Instruct the application to apply changes to state requested by the
// preedit_string, commit_string delete_surrounding_text, and action
// events.
//
// The state relating to these events is double-buffered, and each one
// modifies the pending state. This event replaces the current state with
// the pending state.
//
// The application must proceed by evaluating the changes in the following
// order:
//
// 1. Replace existing preedit string with the cursor.
// 2. Delete requested surrounding text.
// 3. Insert commit string with the cursor at its end.
// 4. Calculate surrounding text to send.
// 5. Insert new preedit text in cursor position.
// 6. Place cursor inside preedit text.
// 7. Perform the requested action.
//
// The serial number reflects the last state of the zwp_text_input_v3
// object known to the compositor. The value of the serial argument must
// be equal to the number of commit requests already issued on that object.
//
// When the client receives a done event with a serial different than the
// number of past commit requests, it must proceed with evaluating and
// applying the changes as normal, except it should not change the current
// state of the zwp_text_input_v3 object. All pending state requests
// (set_surrounding_text, set_content_type and set_cursor_rectangle) on
// the zwp_text_input_v3 object should be sent and committed after
// receiving a zwp_text_input_v3.done event with a matching serial.
type ZwpTextInputV3DoneEvent struct {
	Serial uint32
}

// SetDoneHandler sets the callback for the done event. Pass nil to remove it.
func (self *ZwpTextInputV3) SetDoneHandler(h func(ZwpTextInputV3DoneEvent)) { self.onDone = h }

// ZwpTextInputV3ActionEvent holds the arguments of the zwp_text_input_v3.action event: action performed.
//
// An action was performed on this text input.
//
// Values set with this event are double-buffered. They must be applied
// and reset to initial on the next zwp_text_input_v3.done event.
//
// The initial value of action is none.
//
// Since version 2.
type ZwpTextInputV3ActionEvent struct {
	// Action: action performed.
	Action ZwpTextInputV3Action
	// Serial: serial number of the action event.
	Serial uint32
}

// SetActionHandler sets the callback for the action event. Pass nil to remove it.
// The event exists since version 2.
func (self *ZwpTextInputV3) SetActionHandler(h func(ZwpTextInputV3ActionEvent)) { self.onAction = h }

// ZwpTextInputV3LanguageEvent holds the arguments of the zwp_text_input_v3.language event: notify of language selection.
//
// Notify the application of language used by the input method.
//
// This event will be sent on creation if known and for all subsequent changes.
//
// The language should be specified as an IETF BCP 47 tag.
// Setting an empty string will reset any known language back to the default unknown state.
//
// Since version 2.
type ZwpTextInputV3LanguageEvent struct {
	// Language: new language set by IME.
	Language string
}

// SetLanguageHandler sets the callback for the language event. Pass nil to remove it.
// The event exists since version 2.
func (self *ZwpTextInputV3) SetLanguageHandler(h func(ZwpTextInputV3LanguageEvent)) {
	self.onLanguage = h
}

// ZwpTextInputV3PreeditHintEvent holds the arguments of the zwp_text_input_v3.preedit_hint event: pre-edit.
//
// Notify of contextual hints for the pre-edit string. This
// event is always sent together with a zwp_text_input_v3.preedit_string
// event.
//
// The parameters start and end are counted in bytes relative to the
// beginning of the text buffer submitted through
// zwp_text_input_v3.preedit_string, and represent the substring in the
// pre-edit text affected by the hint.
//
// Multiple events may be submitted if the preedit string has different
// sections. The extent of hints may overlap. The parts of the preedit
// string that are not covered by any zwp_text_input_v3.preedit_hint event,
// the text will be considered unhinted. This is also the case if no
// preedit_hint event is sent.
//
// Clients should provide recognizable visuals to these hints. if they are
// unable to comply with this requisition, it may be preferable for them
// keep the preedit_shown content hint disabled.
//
// Values set with this event are double-buffered. They must be applied
// and reset on the next zwp_text_input_v3.done event.
//
// Since version 2.
type ZwpTextInputV3PreeditHintEvent struct {
	// Start: starting point of the affected substring.
	Start uint32
	// End: end point of the affected substring.
	End uint32
	// Hint: hint to apply.
	Hint ZwpTextInputV3PreeditHint
}

// SetPreeditHintHandler sets the callback for the preedit_hint event. Pass nil to remove it.
// The event exists since version 2.
func (self *ZwpTextInputV3) SetPreeditHintHandler(h func(ZwpTextInputV3PreeditHintEvent)) {
	self.onPreeditHint = h
}

// Dispatch implements wire.Object: it decodes one event and calls its handler.
func (self *ZwpTextInputV3) Dispatch(opcode uint16, r *wire.Reader) error {
	switch opcode {
	case 0: // enter
		var ev ZwpTextInputV3EnterEvent
		ev.Surface, _ = r.Object().(*WlSurface)
		if err := r.Err(); err != nil {
			return err
		}
		if h := self.onEnter; h != nil {
			h(ev)
		}
		return nil
	case 1: // leave
		var ev ZwpTextInputV3LeaveEvent
		ev.Surface, _ = r.Object().(*WlSurface)
		if err := r.Err(); err != nil {
			return err
		}
		if h := self.onLeave; h != nil {
			h(ev)
		}
		return nil
	case 2: // preedit_string
		var ev ZwpTextInputV3PreeditStringEvent
		ev.Text = r.StringPtr()
		ev.CursorBegin = r.Int()
		ev.CursorEnd = r.Int()
		if err := r.Err(); err != nil {
			return err
		}
		if h := self.onPreeditString; h != nil {
			h(ev)
		}
		return nil
	case 3: // commit_string
		var ev ZwpTextInputV3CommitStringEvent
		ev.Text = r.StringPtr()
		if err := r.Err(); err != nil {
			return err
		}
		if h := self.onCommitString; h != nil {
			h(ev)
		}
		return nil
	case 4: // delete_surrounding_text
		var ev ZwpTextInputV3DeleteSurroundingTextEvent
		ev.BeforeLength = r.Uint()
		ev.AfterLength = r.Uint()
		if err := r.Err(); err != nil {
			return err
		}
		if h := self.onDeleteSurroundingText; h != nil {
			h(ev)
		}
		return nil
	case 5: // done
		var ev ZwpTextInputV3DoneEvent
		ev.Serial = r.Uint()
		if err := r.Err(); err != nil {
			return err
		}
		if h := self.onDone; h != nil {
			h(ev)
		}
		return nil
	case 6: // action
		var ev ZwpTextInputV3ActionEvent
		ev.Action = ZwpTextInputV3Action(r.Uint())
		ev.Serial = r.Uint()
		if err := r.Err(); err != nil {
			return err
		}
		if h := self.onAction; h != nil {
			h(ev)
		}
		return nil
	case 7: // language
		var ev ZwpTextInputV3LanguageEvent
		ev.Language = r.String()
		if err := r.Err(); err != nil {
			return err
		}
		if h := self.onLanguage; h != nil {
			h(ev)
		}
		return nil
	case 8: // preedit_hint
		var ev ZwpTextInputV3PreeditHintEvent
		ev.Start = r.Uint()
		ev.End = r.Uint()
		ev.Hint = ZwpTextInputV3PreeditHint(r.Uint())
		if err := r.Err(); err != nil {
			return err
		}
		if h := self.onPreeditHint; h != nil {
			h(ev)
		}
		return nil
	}
	return wire.UnknownEvent(self, opcode)
}

// Destroy sends the zwp_text_input_v3.destroy request: Destroy the wp_text_input.
//
// Destroy the wp_text_input object. Also disables all surfaces enabled
// through this wp_text_input object.
//
// This is a destructor: the proxy must not be used afterwards.
func (self *ZwpTextInputV3) Destroy() {
	msg := self.Begin(0)
	msg.Done()
	self.MarkDestroyed()
}

// Enable sends the zwp_text_input_v3.enable request: Request text input to be enabled.
//
// Requests text input on the surface previously obtained from the enter
// event.
//
// This request must be issued every time the focused text input changes
// to a new one, including within the current surface. Use
// zwp_text_input_v3.disable when there is no longer any input focus on
// the current surface.
//
// Clients must not enable more than one text input on the single seat
// and should disable the current text input before enabling the new one.
// Requests to enable a text input when another text input is enabled
// on the same seat must be ignored by compositor.
//
// This request resets all state associated with previous enable, disable,
// set_surrounding_text, set_text_change_cause, set_content_type, and
// set_cursor_rectangle requests, as well as the state associated with
// preedit_string, commit_string, and delete_surrounding_text events.
//
// The set_surrounding_text, set_content_type and set_cursor_rectangle
// requests must follow if the text input supports the necessary
// functionality.
//
// State set with this request is double-buffered. It will get applied on
// the next zwp_text_input_v3.commit request, and stay valid until the
// next committed enable or disable request.
//
// The changes must be applied by the compositor after issuing a
// zwp_text_input_v3.commit request.
func (self *ZwpTextInputV3) Enable() {
	msg := self.Begin(1)
	msg.Done()
}

// Disable sends the zwp_text_input_v3.disable request: Disable text input on a surface.
//
// Explicitly disable text input on the current surface (typically when
// there is no focus on any text entry inside the surface).
//
// State set with this request is double-buffered. It will get applied on
// the next zwp_text_input_v3.commit request.
func (self *ZwpTextInputV3) Disable() {
	msg := self.Begin(2)
	msg.Done()
}

// SetSurroundingText sends the zwp_text_input_v3.set_surrounding_text request: sets the surrounding text.
//
// Sets the surrounding plain text around the input, excluding the preedit
// text.
//
// The client should notify the compositor of any changes in any of the
// values carried with this request, including changes caused by handling
// incoming text-input events as well as changes caused by other
// mechanisms like keyboard typing.
//
// If the client is unaware of the text around the cursor, it should not
// issue this request, to signify lack of support to the compositor.
//
// Text is UTF-8 encoded, and should include the cursor position, the
// complete selection and additional characters before and after them.
// There is a maximum length of wayland messages, so text can not be
// longer than 4000 bytes.
//
// Cursor is the byte offset of the cursor within text buffer.
//
// Anchor is the byte offset of the selection anchor within text buffer.
// If there is no selected text, anchor is the same as cursor.
//
// If any preedit text is present, it is replaced with a cursor for the
// purpose of this event.
//
// Values set with this request are double-buffered. They will get applied
// on the next zwp_text_input_v3.commit request, and stay valid until the
// next committed enable or disable request.
//
// The initial state for affected fields is empty, meaning that the text
// input does not support sending surrounding text. If the empty values
// get applied, subsequent attempts to change them may have no effect.
func (self *ZwpTextInputV3) SetSurroundingText(text string, cursor int32, anchor int32) {
	msg := self.Begin(3)
	msg.String(text)
	msg.Int(cursor)
	msg.Int(anchor)
	msg.Done()
}

// SetTextChangeCause sends the zwp_text_input_v3.set_text_change_cause request: indicates the cause of surrounding text change.
//
// Tells the compositor why the text surrounding the cursor changed.
//
// Whenever the client detects an external change in text, cursor, or
// anchor posision, it must issue this request to the compositor. This
// request is intended to give the input method a chance to update the
// preedit text in an appropriate way, e.g. by removing it when the user
// starts typing with a keyboard.
//
// cause describes the source of the change.
//
// The value set with this request is double-buffered. It must be applied
// and reset to initial at the next zwp_text_input_v3.commit request.
//
// The initial value of cause is input_method.
func (self *ZwpTextInputV3) SetTextChangeCause(cause ZwpTextInputV3ChangeCause) {
	msg := self.Begin(4)
	msg.Uint(uint32(cause))
	msg.Done()
}

// SetContentType sends the zwp_text_input_v3.set_content_type request: set content purpose and hint.
//
// Sets the content purpose and content hint. While the purpose is the
// basic purpose of an input field, the hint flags allow to modify some of
// the behavior.
//
// Values set with this request are double-buffered. They will get applied
// on the next zwp_text_input_v3.commit request.
// Subsequent attempts to update them may have no effect. The values
// remain valid until the next committed enable or disable request.
//
// The initial value for hint is none, and the initial value for purpose
// is normal.
func (self *ZwpTextInputV3) SetContentType(hint ZwpTextInputV3ContentHint, purpose ZwpTextInputV3ContentPurpose) {
	msg := self.Begin(5)
	msg.Uint(uint32(hint))
	msg.Uint(uint32(purpose))
	msg.Done()
}

// SetCursorRectangle sends the zwp_text_input_v3.set_cursor_rectangle request: set cursor position.
//
// Marks an area around the cursor as a x, y, width, height rectangle in
// surface local coordinates.
//
// Allows the compositor to put a window with word suggestions near the
// cursor, without obstructing the text being input.
//
// If the client is unaware of the position of edited text, it should not
// issue this request, to signify lack of support to the compositor.
//
// Values set with this request are double-buffered. They will get applied
// on the next zwp_text_input_v3.commit request, and stay valid until the
// next committed enable or disable request.
//
// The initial values describing a cursor rectangle are empty. That means
// the text input does not support describing the cursor area. If the
// empty values get applied, subsequent attempts to change them may have
// no effect.
//
// As of version 2, the zwp_text_input_v3.commit request does not apply
// values sent with this request. Instead, it stores them in a separate
// "committed" area. The committed values, if still valid, get applied on
// the next wl_surface.commit request on the surface with text-input focus.
// Both committed and applied values get invalidated on:
//
// - the next committed enable or disable request, or
// - a change of the focused surface of the text-input (leave or enter events).
//
// This double stage application allows the compositor to position
// the input method popup in the same frame as the contents
// of the text on the surface are updated.
func (self *ZwpTextInputV3) SetCursorRectangle(x int32, y int32, width int32, height int32) {
	msg := self.Begin(6)
	msg.Int(x)
	msg.Int(y)
	msg.Int(width)
	msg.Int(height)
	msg.Done()
}

// Commit sends the zwp_text_input_v3.commit request: commit state.
//
// Atomically applies state changes recently sent to the compositor.
//
// The commit request establishes and updates the state of the client, and
// must be issued after any changes to apply them.
//
// Text input state (enabled status, content purpose, content hint,
// surrounding text and change cause, cursor rectangle) is conceptually
// double-buffered within the context of a text input, i.e. between a
// committed enable request and the following committed enable or disable
// request.
//
// Protocol requests modify the pending state, as opposed to the current
// state in use by the input method. A commit request atomically applies
// all pending state, replacing the current state. After commit, the new
// pending state is as documented for each related request.
//
// Requests are applied in the order of arrival.
//
// Neither current nor pending state are modified unless noted otherwise.
//
// The compositor must count the number of commit requests coming from
// each zwp_text_input_v3 object and use the count as the serial in done
// events.
func (self *ZwpTextInputV3) Commit() {
	msg := self.Begin(7)
	msg.Done()
}

// SetAvailableActions sends the zwp_text_input_v3.set_available_actions request: set the available actions.
//
// Set the actions available for this text input.
//
// Values set with this request are double-buffered. They will get applied
// on the next zwp_text_input_v3.commit request.
//
// If the available_actions array contains the none action, or contains the
// same action multiple times, the compositor must raise the invalid_action
// protocol error.
//
// Initially, no actions are available.
//
// Since version 2.
func (self *ZwpTextInputV3) SetAvailableActions(availableActions []byte) {
	msg := self.Begin(8)
	msg.Array(availableActions)
	msg.Done()
}

// ShowInputPanel sends the zwp_text_input_v3.show_input_panel request: show input panel.
