// ZwpTextInputManagerV3InterfaceName is the protocol name of ZwpTextInputManagerV3, as advertised by wl_registry.global.
const ZwpTextInputManagerV3InterfaceName = "zwp_text_input_manager_v3"

// ZwpTextInputManagerV3Version is the highest version of zwp_text_input_manager_v3 known to these bindings.
