// GetTextInput sends the zwp_text_input_manager_v3.get_text_input request: create a new text input object.
//
// Creates a new text-input object for a given seat.
//
// The new object has the same version as the receiver.
func (self *ZwpTextInputManagerV3) GetTextInput(seat *WlSeat) *ZwpTextInputV3 {
	msg := self.Begin(1)
	proxy_ := &ZwpTextInputV3{}
	msg.NewObject(proxy_, self.Version())
	var seatID uint32
	if seat != nil {
		seatID = seat.ID()
	}
	msg.Object(seatID)
	msg.Done()
	return proxy_
}
